        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){string key=request.Headers.Authorization==null?"":request.Headers.Authorization.Parameter;AuthSafe&=request.RequestUri.Host=="api.commandcode.ai"&&(key=="fixture-a"||key=="fixture-b");if(request.Method==HttpMethod.Get){Interlocked.Increment(ref Reads);return Response(200,"{\"object\":\"list\",\"data\":[{\"id\":\"fixture-open\",\"supported_endpoints\":[\"/chat/completions\",\"/responses\"]},{\"id\":\"fixture-claude\",\"supported_endpoints\":[\"/messages\"]}]}");}lock(Posts)Posts.Add(key);LastBody=await request.Content.ReadAsStringAsync();LastEndpoint=request.RequestUri.AbsolutePath;LastQuery=request.RequestUri.Query;if(Mode=="network")throw new HttpRequestException("fixture connection interrupted");if(Mode=="limit"&&key=="fixture-a"){var response=Response(429,"{\"error\":{\"code\":\"rate_limit\"}}");response.Headers.RetryAfter=new RetryConditionHeaderValue(TimeSpan.FromSeconds(60));return response;}if(Mode=="upgrade"&&key=="fixture-a")return Response(403,"{\"error\":{\"code\":\"upgrade_required\"}}");if(Mode=="quota"&&key=="fixture-a")return Response(402,"{\"error\":{\"code\":\"insufficient_credits\"}}");if(Mode=="forbidden")return Response(403,"{\"error\":{\"code\":\"policy_denied\"}}");if(Mode=="cancel"){Entered.TrySetResult(true);try{await Task.Delay(Timeout.Infinite,token);}catch(OperationCanceledException){Cancelled.TrySetResult(true);throw;}}if(Mode=="concurrent"&&key=="fixture-a"){Entered.TrySetResult(true);await Release.Task;}if(Mode=="broken-stream")return new HttpResponseMessage(HttpStatusCode.OK){Content=new StreamContent(new BrokenStream())};if(Mode=="messages")return Response(200,"data: {\"type\":\"message_start\",\"message\":{\"usage\":{\"input_tokens\":12,\"cache_read_input_tokens\":8}}}\n\ndata: {\"type\":\"message_delta\",\"usage\":{\"output_tokens\":5}}\n\n","text/event-stream");if(Mode=="stream")return Response(200,"data: {\"choi