    private static ProxyAccount[] Accounts(){return new[]{new ProxyAccount{Id="a",Name="Fixture A",Key="fixture-a",Balance=10,CredentialState="valid"},new ProxyAccount{Id="b",Name="Fixture B",Key="fixture-b",Balance=5,CredentialState="valid"}};}
