    private static async Task RunAsync(){string key=LocalProxy.GenerateKey();Check(key.StartsWith("mw_")&&key!=LocalProxy.GenerateKey(),"proxy keys not random");string encrypted=CommandCodeManager.Core.Encrypt(key);Check(!encrypted.Contains(key)&&CommandCodeManager.Core.Decrypt(encrypted)==key,"proxy key not DPAPI protected");var handler=new Handler();int port=Port();using(var proxy=new LocalProxy(Accounts,handler))using(var client=Client(port,key)){proxy.Configure(port,key,new[]{"a","b"},true);using(var unauth=Client(port,"wrong")){var response=await unauth.GetAsync("/v1/models");Check((int)response.StatusCode==401&&handler.Reads==0,"bad local key reached upstream");}using(var request=new HttpRequestMessage(HttpMethod.Get,"/v1/models")){request.Headers.TryAddWithoutValidation("Origin","https://foreign.example");Check((int)(await client.SendAsync(request)).StatusCode==403&&handler.Reads==0,"browser origin allowed");}var models=await client.GetAsync("/v1/models");string catalog=await models.Content.ReadAsStringAsync();Check(models.IsSuccessStatusCode&&catalog.Contains("fixture-open")&&catalog.Contains("\"object\":\"list\""),"model list incompatible");Check(handler.Reads==2,"catalog did not include both accounts");Check((int)(await Post(client,"/v1/chat/completions","{\"model\":\"missing\"}")).StatusCode==400&&handler.Posts.Count==0,"unknown model charged");handler.Mode="limit";var result=await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\",\"messages\":[{\"role\":\"user\",\"content\":\"fixture\"}]}");Check(result.IsSuccessStatusCode&&handler.Posts.SequenceEqual(new[]{"fixture-a","fixture-b"}),"429 failover failed");Check(handler.AuthSafe&&handler.LastEndpoint=="/provider/v1/chat/completions","credential or path leaked");await Task.Delay(30);var logs=Logs(proxy);Check(logs.Length==2&&Convert.ToInt32(logs[0]["input"])==12&&Convert.ToInt32(logs[0]["output"])==5&&Convert.ToInt32(State(proxy)["cooling"])==1,"usage or cooldown incorrect");handler.Posts.Clear();handler.Mode="success";await Post(client,"/v1/responses","{\"model\":\"fixture-open\",\"input\":\"fixture\"}");Check(handler.Posts.SequenceEqual(new[]{"fixture-b"})&&handler.LastEndpoint=="/provider/v1/responses","cooling account reused or response path wrong");proxy.ClearCooldown();handler.Posts.Clear();handler.Mode="quota";Check((await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\"}")).IsSuccessStatusCode&&handler.Posts.Count==2,"credit failover failed");proxy.ClearCooldown();handler.Posts.Clear();handler.Mode="upgrade";Check((await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\"}")).IsSuccessStatusCode&&handler.Posts.Count==2,"known unsupported plan did not fail over");proxy.ClearCooldown();handler.Posts.Clear();handler.Mode="stream";var streamed=await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\",\"stream\":true}");string sse=await streamed.Content.ReadAsStringAsync();Check(sse.Contains("测试")&&sse.Contains("[DONE]")&&handler.LastBody.Contains("include_usage"),"SSE changed or usage not requested");handler.Mode="messages";await Post(client,"/v1/messages","{\"model\":\"fixture-claude\",\"stream\":true,\"max_tokens\":16}");await Task.Delay(30);Check(Convert.ToInt32(Logs(proxy)[0]["input"])==20&&Convert.ToInt32(Logs(proxy)[0]["output"])==5&&handler.LastEndpoint=="/provider/v1/messages","Anthropic usage or routing failed");handler.Posts.Clear();handler.Mode="network";Check((int)(await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\"}")).StatusCode==502&&handler.Posts.Count==1,"uncertain network failure replayed");handler.Posts.Clear();handler.Mode="forbidden";Check((int)(await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\"}")).StatusCode==403&&handler.Posts.Count==1,"policy refusal replayed");handler.Posts.Clear();handler.Mode="broken-stream";var broken=await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\",\"stream\":true}");string partial=await broken.Content.ReadAsStringAsync();Check(partial.Contains("partial")&&handler.Posts.Count==1,"partial response replayed");handler.Posts.Clear();handler.Mode="concurrent";var first=Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\"}");Check(await Task.WhenAny(handler.Entered.Task,Task.Delay(3000))==handler.Entered.Task,"concurrency fixture failed");var second=await Post(client,"/v1/chat/completions","{\"model\":\"fixture-open\"}");Check(second.IsSuccessStatusCode&&handler.Posts.Contains("fixture-b"),"busy account not balanced");handler.Release.TrySetResult(true);Check((await first).IsSuccessStatusCode,"first concurrent request failed");await Task.Delay(30);string next=LocalProxy.GenerateKey();proxy.Configure(port,next,new[]{"a","b"},true);Check((int)(await client.GetAsync("/health")).StatusCode==401,"old key still accepted");using(var current=Client(port,next))Check((await current.GetAsync("/health")).IsSuccessStatusCode,"new key rejected");handler.Mode="success";using(var raw=new TcpClient()){await raw.ConnectAsync(IPAddress.Loopback,port);string body="{\"model\":\"fixture-open\"}";string wire="POST /v1/chat/completions HTTP/1.1\r\nHost: 127.0.0.1:"+port+"\r\nAuthorization: Bearer "+next+"\r\nTransfer-Encoding: chunked\r\n\r\n"+Encoding.UTF8.GetByteCount(body).ToString("x")+"\r\n"+body+"\r\n0\r\n\r\n";byte[] bytes=Encoding.UTF8.GetBytes(wire);await raw.GetStream().WriteAsync(bytes,0,bytes.Length);using(var reader=new StreamReader(raw.GetStream()))Check((await reader.ReadToEndAsync()).StartsWith("HTTP/1.1 200"),"chunked request rejected");}handler.Posts.Clear();handler.Entered=new TaskCompletionSource<bool>();handler.Mode="cancel";using(var raw=new TcpClient()){await raw.ConnectAsync(IPAddress.Loopback,port);string body="{\"model\":\"fixture-open\"}";byte[] wire=Encoding.UTF8.GetBytes("POST /v1/chat/completions HTTP/1.1\r\nHost: 127.0.0.1:"+port+"\r\nAuthorization: Bearer "+next+"\r\nContent-Length: "+Encoding.UTF8.GetByteCount(body)+"\r\n\r\n"+body);await raw.GetStream().W